# For each point, prints the ID of the farthest point, smallest ID on ties
N=int(input())
X=[None for _ in range(N+1)]
Y=[None for _ in range(N+1)]
for n in range(1,N+1):
  X[n],Y[n]=map(int,input().split())
for i in range(1,N+1):
  k,d=0,-float('inf')
  for j in range(1,N+1):
    dn=(X[i]-X[j])**2+(Y[i]-Y[j])**2
    if dn>d:
      k,d=j,dn
  print(k)

# For each point, keeps the candidate with the smallest squared distance, skipping the point itself
N=int(input())
X=[None for _ in range(N+1)]
Y=[None for _ in range(N+1)]
for n in range(1,N+1):
  X[n],Y[n]=map(int,input().split())
for i in range(1,N+1):
  k,d=None,0
  for j in range(1,N+1):
    if i == j:
      continue
    dn=(X[i]-X[j])**2+(Y[i]-Y[j])**2
    if dn > d or (dn == d and j < k):
      k,d=j,dn
  print(k)

